 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            local = {(y-minr, x-minc) for y, x in cells}
            pieces.append({"color": color, "cells": local, "r": minr, "c": minc,
                           "height": maxr-minr+1, "width": maxc-minc+1,
                           "hole": _has_hole(local, maxr-minr+1, maxc-minc+1)})
    return pieces


def _has_hole(cells, h, w):
    empty = {(r, c) for r in range(h) for c in range(w) if (r, c) not in cells}
    outside = set()
    q = deque()
    for r, c in empty:
        if r == 0 or c == 0 or r == h-1 or c == w-1:
            outside.add((r, c))
            q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if (nr, nc) in empty and (nr, nc) not in outside:
                outside.add((nr, nc))
                q.append((nr, nc))
    return bool(empty - outside)


def transform(grid):
    h, w = len(grid), len(grid[0])
    pieces = _components(grid)
    result = [[0] * w for _ in range(h)]
    for direction in ("up", "down"):
        group = [p for p in pieces if p["hole"] == (direction == "up")]
        if direction == "up":
            group.sort(key=lambda p: (p["r"], p["c"]))
        else:
            group.sort(key=lambda p: (-p["r"]-p["height"], p["c"]))
        occupied = set()
        for p in group:
            if direction == "up":
                positions = range(0, p["r"] + 1)
            else:
                positions = range(h - p["height"], p["r"] - 1, -1)
            chosen = None
            for top in positions:
                placed = {(top + y, p["c"] + x) for y, x in p["cells"]}
                if not (placed & occupied):
                    chosen = placed
                    break
            if chosen is None:
                chosen = {(p["r"] + y, p["c"] + x) for y, x in p["cells"]}
            occupied.update(chosen)
            for y, x in chosen:
                result[y][x] = p["color"]
    return result
